SELECT 
FROM shop_order
WHERE order_id = #{orderId}
  AND uid = #{uid}
LIMIT 1

SELECT 
FROM shop_order
WHERE order_id = #{orderId}
  AND uid = #{uid}
  AND IFNULL(is_del, 0) = 0
LIMIT 1

mapper.update:
UPDATE shop_order
SET paid = #{paid},
    status = #{status},
    update_time = NOW()
WHERE id = #{id}
  AND paid = #{pendingPaid}

mapper.select:
SELECT t1.id, t1.uid, t1.product_id AS productId, t1.sku_id AS skuId, t1.cart_num AS cartNum, t1.seckill_id AS seckillId, t1.bargain_id AS bargainId, t1.status, t1.create_time AS createTime, t1.update_time AS updateTime, t2.sku AS sku, COALESCE(t2.flash_price, t4.flash_price, t2.price) AS price, t3.postage AS postage, t3.product_name AS productName, t3.image AS image, t3.cate_id AS cateId, t3.give_integral AS giveIntegral FROM shop_product_cart t1 LEFT JOIN shop_product_attr_value t2 ON t1.sku_id = t2.id LEFT JOIN shop_product t3 ON t1.product_id = t3.id LEFT JOIN shop_flash_sale t4 ON t1.seckill_id = t4.id AND t4.is_del = 0
AND t1.uid = #{uid}
AND t1.status = #{status}
AND t1.id IN
#{cartId}
